//#region src/renderer/stores/backup.ts
/**
* 备份 Store - 管理腾讯云 COS 配置、备份状态和备份历史。
* SecretKey、SecurityToken 和恢复密码不写入持久化状态。
*/
var useBackupStore = defineStore("backup", () => {
	const status = ref({
		status: "unconfigured",
		lastBackupTime: null,
		lastBackupSize: null,
		dirty: false,
		lastError: null,
		credentialConfigured: false
	});
	const config = reactive({
		region: "",
		bucket: "",
		prefix: "",
		secretId: "",
		secretKey: "",
		securityToken: "",
		autoBackup: true,
		retentionCount: 30,
		restorePassword: ""
	});
	const history = ref([]);
	const credentialConfigured = ref(false);
	async function loadStatus() {
		status.value = await api.backup.getStatus();
	}
	async function loadConfig() {
		const result = await api.backup.getConfig();
		credentialConfigured.value = result.credentialConfigured;
		if (result.config) Object.assign(config, result.config);
	}
	async function saveConfig() {
		await api.backup.saveConfig(config);
		credentialConfigured.value = !!(config.secretId && config.secretKey);
	}
	async function testConnection() {
		return api.backup.testConnection(config);
	}
	async function loadHistory() {
		const result = await api.backup.list();
		history.value = result.rows;
	}
	return {
		status,
		config,
		history,
		credentialConfigured,
		loadStatus,
		loadConfig,
		saveConfig,
		testConnection,
		loadHistory
	};
});
